        end
        local function mapCFrame(map)
            if not map then return nil end
            local coins = map:FindFirstChild("CoinContainer")
            if coins then
                local coin = coins:FindFirstChild("Coin_Server") or coins:FindFirstChild("CoinVisual") or coins:FindFirstChildWhichIsA("BasePart", true)
                if coin then
                    if coin:IsA("BasePart") then return coin.CFrame + Vector3.new(0, 5, 0) end
                    local p = firstPart(coin)
                    if p then return p.CFrame + Vector3.new(0, 5, 0) end
                end
                for _, child in ipairs(coins:GetChildren()) do
                    local p = firstPart(child)
                    if p then return p.CFrame + Vector3.new(0, 5, 0) end
                end
            end
            return pickFrom(map)
        end
                local function lobbyCFrame()
            local map = findMapModel()
            local function fromSpawns(folder)
                if not folder then return nil end
                local parts = {}
                for _, child in ipairs(folder:GetChildren()) do
                    local p = firstPart(child)
                    if p then parts[#parts + 1] = p end
                end
                if #parts == 0 then
                    local p = firstPart(folder)
                    if p then parts[1] = p end
                end
                if #parts > 0 then return parts[math.random(1, #parts)].CFrame + Vector3.new(0, 3, 0) end
            end
            local function fromInst(inst)
                if not inst then return nil end
                if map and (inst == map or inst:IsDescendantOf(map)) then return nil end
                local cf = fromSpawns(inst:FindFirstChild("Spawns") or inst:FindFirstChild("Spawn") or inst:FindFirstChild("SpawnLocation") or inst:FindFirstChild("PlayerSpawns"))
                if cf then return cf end
                local sl = inst:FindFirstChildWhichIsA("SpawnLocation", true)
                if sl then return sl.CFrame + Vector3.new(0, 4, 0) end
                if inst:IsA("SpawnLocation") or inst:IsA("BasePart") then
                    return inst.CFrame + Vector3.new(0, 4, 0)
                end
                if inst:IsA("Model") then
                    local ok, pivot = pcall(function() return inst:GetPivot() end)
                    if ok and typeof(pivot) == "CFrame" then return pivot * CFrame.new(0, 6, 0) end
                end
            end
            local function isLobbyName(n)
                n = string.lower(tostring(n or ""))
                return n == "lobby" or string.find(n, "lobby", 1, true) ~= nil
                    or n == "waiting" or n == "waitingroom" or n == "vote" or n == "voting" or n == "votingroom"
            end
            for _, child in ipairs(workspace:GetChildren()) do
                if isLobbyName(child.Name) then
                    local cf = fromInst(child)
                    if cf then return cf end
                end
            end
            local okDesc, descendants = pcall(function() return workspace:GetDescendants() end)
            if okDesc and descendants then
                for i = 1, #descendants do
                    local inst = descendants[i]
                    local n = inst.Name
                    if (n == "Spawns" or n == "Spawn" or n == "PlayerSpawns") and inst.Parent and isLobbyName(inst.Parent.Name) then
                        local cf = fromSpawns(inst)
                        if cf then return cf end
                    elseif isLobbyName(n) and (inst:IsA("Model") or inst:IsA("Folder")) then
                        local cf = fromInst(inst)
                        if cf then return cf end
                    end
                end
                for i = 1, #descendants do
                    local inst = descendants[i]
                    if inst:IsA("SpawnLocation") and not (map and inst:IsDescendantOf(map)) then
                        return inst.CFrame + Vector3.new(0, 4, 0)
                    end
                end
                for i = 1, #descendants do
                    local inst = descendants[i]
                    if (inst.Name == "Spawns" or inst.Name == "Spawn") and not (map and inst:IsDescendantOf(map)) then
                        local cf = fromSpawns(inst)
                        if cf then return cf end
                    end
                end
            end
            return nil
        end
        local function tpToPlayer(player)
            if not player or player == LocalPlayer then notify("Некого телепортировать", 2); return end
            local char = player.Character
            local hrp = char and (char:FindFirstChild("HumanoidRootPart") or char:FindFirstChild("UpperTorso") or char:FindFirstChild("Torso"))
            if not hrp then notify(player.Name .. " без персонажа", 2); return end
            if tpToCF(hrp.CFrame * CFrame.new(0, 2, 3.5)) then
                notify("TP → " .. player.Name, 2)
            end
        end
        local function currentMurder()
            if validTarget(murderer) then return murderer end
            local byKnife = findByKnife()
            if validTarget(byKnife) then return byKnife end
            for _, player in ipairs(getPlayers()) do
                if roleCache[player.UserId] == "murderer" and validTarget(player) then return player end
            end
        end
        local function currentSheriff()
            if validTarget(sheriff) then return sheriff end
            if validTarget(hero) then return hero end
            local byGun = findByGun()
            if validTarget(byGun) then return byGun end
            for _, player in ipairs(getPlayers()) do
                local role = roleCache[player.UserId]
                if (role == "sheriff" or role == "hero") and validTarget(player) then return player end
            end
        end

        local tpHolder = panel("Teleport", "Карта · лобби · роли")
        makeBtn(tpHolder, "Teleport to Map", function()
            local map = findMapModel()
            if not map then notify("Карта не найдена (раунд не начался)", 3); return end
            local cf = mapCFrame(map)
            if cf and tpToCF(cf) then notify("Телепорт на карту", 2) else notify("Нет точки спавна на карте", 3) end
        end)
        makeBtn(tpHolder, "Teleport to Lobby", function()
            local cf = lobbyCFrame()
            if not cf then notify("Лобби не найдено", 3); return end
            if tpToCF(cf) then notify("Телепорт в лобби", 2) end
        end)
        makeBtn(tpHolder, "Teleport to Murder", function()
            local target = currentMurder()
            if not target then notify("Murder не найден", 3); return end
            tpToPlayer(target)
        end)
        makeBtn(tpHolder, "Teleport to Sheriff", function()
            local target = currentSheriff()
            if not target then notify("Sheriff не найден", 3); return end
            tpToPlayer(target)
        end)

        local listHolder = panel("Players", "Как в Fling → Lists")
        local roleLabel = New("TextLabel", { Parent = listHolder, Size = UDim2.new(1, 0, 0, 22), BackgroundTransparency = 1,
            Text = "Murder: —  ·  Sheriff: —", TextColor3 = C.dim, TextSize = 13, Font = Enum.Font.Gotham, TextXAlignment = Enum.TextXAlignment.Left })
        local function refreshRoles()
            local m, s = currentMurder(), currentSheriff()
            roleLabel.Text = "Murder: " .. (m and m.Name or "—") .. "  ·  Sheriff: " .. (s and s.Name or "—")
        end
        local ddRow = New("Frame", { Parent = listHolder, Size = UDim2.new(1, 0, 0, 56), BackgroundTransparency = 1 })
        text(ddRow, "▸ Player", 16, UDim2.fromOffset(0, 10))
        local ddBtn = New("TextButton", { Parent = ddRow, AnchorPoint = Vector2.new(1, 0), Position = UDim2.new(1, 0, 0, 4), Size = UDim2.fromOffset(190, 42),
            BackgroundColor3 = C.surface, Text = "None  ⌄", TextColor3 = C.text, TextSize = 14, Font = Enum.Font.Gotham, AutoButtonColor = false, ZIndex = 5 })
        corner(ddBtn, 10); stroke(ddBtn)
        local popup
        local function closePopup() if popup then popup:Destroy(); popup = nil end end
        local function playerNames()
            local names = { "None" }
            for _, player in ipairs(getPlayers()) do
                if player ~= LocalPlayer then names[#names + 1] = player.Name end
            end
            table.sort(names, function(a, b)
                if a == "None" then return true end
                if b == "None" then return false end
                return string.lower(a) < string.lower(b)
            end)
            return names
        end
        local function openPopup()
            closePopup()
            refreshRoles()
            local names = playerNames()
            local scaleVal = (scale and scale.Scale) or 1
            popup = New("ScrollingFrame", { Parent = gui, Position = UDim2.fromOffset(ddBtn.AbsolutePosition.X / scaleVal, (ddBtn.AbsolutePosition.Y + ddBtn.AbsoluteSize.Y + 4) / scaleVal),
                Size = UDim2.fromOffset(ddBtn.AbsoluteSize.X / scaleVal, math.min(#names * 38, 190)), CanvasSize = UDim2.fromOffset(0, #names * 38),
                BackgroundColor3 = C.surface, BorderSizePixel = 0, ScrollBarThickness = 4, ZIndex = 50 })
            corner(popup, 10); stroke(popup, C.accent, .2)
            New("UIListLayout", { Parent = popup, SortOrder = Enum.SortOrder.LayoutOrder })
            for _, name in ipairs(names) do
                local item = New("TextButton", { Parent = popup, Size = UDim2.new(1, 0, 0, 38), BackgroundTransparency = 1, Text = tostring(name),
                    TextColor3 = C.text, TextSize = 14, Font = Enum.Font.Gotham, ZIndex = 51, AutoButtonColor = false })
                local function pick()
                    ddBtn.Text = tostring(name) .. "  ⌄"
                    closePopup()
                    if name == "None" then return end
                    local player = Players:FindFirstChild(name)
                    if player then tpToPlayer(player) end
                end
                item.MouseButton1Click:Connect(pick)
                item.Activated:Connect(pick)
            end
        end
        ddBtn.MouseButton1Click:Connect(openPopup)
        ddBtn.Activated:Connect(openPopup)
        local bus = getgenv().__NoirV4RoleBus
        if bus and bus.Subscribe then bus:Subscribe(function() task.defer(refreshRoles) end) end
        refreshRoles()
    end
end

do
    local function buildAutofarmUI()
        local page = win:FindFirstChild("FarmContent")
        local col = page and page:FindFirstChild("NoirColumn1")
        if page and col then
            local function panel(title, subtitle)
