                New("UIPadding", { Parent = holder, PaddingBottom = UDim.new(0, 12) })
                return holder
            end
            local function makeToggle(parent, label, callback, startOn)
                local state = false
                local r = New("Frame", { Parent = parent, Size = UDim2.new(1, 0, 0, 52), BackgroundTransparency = 1 })
                text(r, label, 16, UDim2.fromOffset(0, 10))
                local pill = New("TextButton", { Parent = r, AnchorPoint = Vector2.new(1, 0), Position = UDim2.new(1, 0, 0, 8), Size = UDim2.fromOffset(64, 34),
                    BackgroundColor3 = C.off, Text = "", AutoButtonColor = false })
                corner(pill, 17); stroke(pill, C.border, .55)
                local dot = New("Frame", { Parent = pill, Position = UDim2.fromOffset(4, 4), Size = UDim2.fromOffset(26, 26), BackgroundColor3 = Color3.fromRGB(150, 155, 162) })
                corner(dot, 13)
                local function apply(v)
                    state = v == true
                    TweenService:Create(pill, TweenInfo.new(.22, Enum.EasingStyle.Quart, Enum.EasingDirection.Out), { BackgroundColor3 = state and C.accent or C.off }):Play()
                    TweenService:Create(dot, TweenInfo.new(.32, Enum.EasingStyle.Quart, Enum.EasingDirection.Out), {
                        Position = state and UDim2.fromOffset(34, 4) or UDim2.fromOffset(4, 4),
                        BackgroundColor3 = state and Color3.fromRGB(255, 255, 255) or Color3.fromRGB(150, 155, 162)
                    }):Play()
                    callback(state)
                end
                local last = 0
                local function fire()
                    local now = os.clock()
                    if now - last < .18 then return end
                    last = now
                    apply(not state)
                end
                pill.MouseButton1Click:Connect(fire)
                pill.Activated:Connect(fire)
                if startOn == true then apply(true) end
            end
            local farming, gunFarm, auraOn, resetFull, killAllOn, shootMurdOn, noRenderOn = false, false, false, false, false, false, false
            local bagIsFull, auraRadius = false, 8
            local noclipConn, auraConn, statusLbl
            local fopt = { method = "Standard", spd = 30, dly = 10, avoid = false, rstM = false, rstS = false, ret = "Map" }
            local lastMapCF, lastCoin, holdReturnUntil, farmTw = nil, nil, 0, nil
            local function farmKey(k) return "Autofarm::" .. k end
            local function farmRead(bag, key, def)
                local store = NoirPersistence.data[bag]
                if type(store) ~= "table" then return def end
                local v = store[farmKey(key)]
                if v == nil then return def end
                return v
            end
            local function farmWrite(bag, key, val)
                NoirPersistence.data[bag][farmKey(key)] = val
                NoirPersistence.Save()
            end
            fopt.spd = math.clamp(tonumber(farmRead("sliders", "Tween Speed (%)", 30)) or 30, 1, 100)
            fopt.dly = math.clamp(tonumber(farmRead("sliders", "Tween Delay (%)", 10)) or 10, 0, 100)
            fopt.method = farmRead("dropdowns", "Method", "Standard")
            if fopt.method ~= "Lay" then fopt.method = "Standard" end
            fopt.ret = farmRead("dropdowns", "Return To", "Map")
            if fopt.ret ~= "Above Map" and fopt.ret ~= "Lobby" then fopt.ret = "Map" end
            fopt.avoid = farmRead("toggles", "Farm Avoid Murderer", false) == true
            fopt.rstM = farmRead("toggles", "Auto Reset As Murderer", false) == true
            fopt.rstS = farmRead("toggles", "Auto Reset As Sheriff", false) == true
            auraRadius = tonumber(farmRead("sliders", "Aura radius", 8)) or 8
            local origDestroyH = workspace.FallenPartsDestroyHeight
            local function setStatus(msg)
                if statusLbl then statusLbl.Text = msg end
            end
            local function touch(a, b)
                pcall(function()
                    firetouchinterest(a, b, 0)
                    firetouchinterest(a, b, 1)
                end)
            end
            local function getContainer()
                for _, child in ipairs(workspace:GetChildren()) do
                    if child:IsA("Model") then
                        local inner = child:FindFirstChild("CoinContainer")
                        if inner then return inner, child end
                    end
                end
                local box = workspace:FindFirstChild("CoinContainer")
                if box then return box, box.Parent end
                return nil, nil
            end
            local function getCoinParts()
                local parts, box = {}, getContainer()
                if not box then return parts end
                for _, child in ipairs(box:GetChildren()) do
                    if child.Name == "Coin_Server" or child.Name == "CoinVisual" or child.Name == "Coin" or child.Name == "Candy" or child:FindFirstChild("TouchInterest") then
                        if child:IsA("BasePart") then
                            parts[#parts + 1] = child
                        else
                            local p = child:FindFirstChildWhichIsA("BasePart", true)
                            if p then parts[#parts + 1] = p end
                        end
                    end
                end
                if #parts == 0 then
                    local ok, descs = pcall(function() return box:GetDescendants() end)
                    if ok and descs then
                        for n = 1, #descs do
                            local d = descs[n]
                            if d:IsA("BasePart") and d:FindFirstChild("TouchInterest") then
                                parts[#parts + 1] = d
                            end
                        end
                    end
                end
                return parts
            end
            local function poseAt(part)
                local pos = part.Position
                if fopt.method == "Lay" then
                     
                    return CFrame.new(pos.X, pos.Y - 2, pos.Z) * CFrame.Angles(math.pi / 2, 0, 0)
                end
                 
                return CFrame.new(pos.X, pos.Y + 2.4, pos.Z)
            end
            local function freezeRoot(r, on)
                if not r then return end
                pcall(function()
                    r.Anchored = on and true or false
                    r.AssemblyLinearVelocity = Vector3.zero
                    r.AssemblyAngularVelocity = Vector3.zero
                end)
            end
            local function returnCFrame()
                if fopt.ret == "Lobby" then
                    local cf = lobbyCFrame and lobbyCFrame()
                    if cf then return cf end
                    for _, name in ipairs({ "Lobby", "LobbyMap", "Voting", "Waiting" }) do
                        local inst = workspace:FindFirstChild(name)
                        local p = inst and inst:FindFirstChildWhichIsA("BasePart", true)
                        if p then return p.CFrame + Vector3.new(0, 4, 0) end
                    end
                    return lastMapCF
                end
                local map = findMapModel and findMapModel()
                local cf = (mapCFrame and mapCFrame(map)) or lastMapCF
                if not cf then return nil end
                if fopt.ret == "Above Map" then
                    return cf + Vector3.new(0, 40, 0)
                end
                return cf
            end
            local function tweenTo(cf)
                local r = localRoot()
                if not r or not cf then return end
                if farmTw then pcall(function() farmTw:Cancel() end); farmTw = nil end
                local dist = (r.Position - cf.Position).Magnitude
                if dist <= 2.5 then
                    freezeRoot(r, true)
                    r.CFrame = cf
                    freezeRoot(r, false)
                    return
                end
                freezeRoot(r, true)
                local spd = 8 + fopt.spd * 0.55
                local dur = math.clamp(dist / math.max(spd, 10), 0.08, 1.35)
                farmTw = TweenService:Create(r, TweenInfo.new(dur, Enum.EasingStyle.Linear), { CFrame = cf })
                farmTw:Play()
                local t0 = os.clock()
                while farming and os.clock() - t0 < dur + 0.02 do
                    if not farmTw or farmTw.PlaybackState ~= Enum.PlaybackState.Playing then break end
                    task.wait()
                end
                if farmTw then pcall(function() farmTw:Cancel() end); farmTw = nil end
                if r.Parent then r.CFrame = cf end
                freezeRoot(r, false)
            end
            local function setNoclip(on)
                if noclipConn then noclipConn:Disconnect(); noclipConn = nil end
                local char = LocalPlayer.Character
                if not on then
                    if char then
                        for _, p in ipairs(char:GetChildren()) do
                            if p:IsA("BasePart") then p.CanCollide = true end
                        end
                    end
                    return
                end
                noclipConn = RunService.Stepped:Connect(function()
                    if not farming then return end
                    local c = LocalPlayer.Character
                    if not c then return end
                    for _, p in ipairs(c:GetChildren()) do
                        if p:IsA("BasePart") then p.CanCollide = false end
                    end
                end)
            end
            local function magnetCoins()
                local char = LocalPlayer.Character
                local root = localRoot()
                if not char or not root then return 0 end
                freezeRoot(root, false)
                local parts = getCoinParts()
                for n = 1, #parts do
                    local part = parts[n]
                    if part and part.Parent then
                        touch(root, part)
                        for _, bp in ipairs(char:GetChildren()) do
                            if bp:IsA("BasePart") then touch(bp, part) end
                        end
                    end
                end
                return #parts
            end
            local function collectAura()
                local root = localRoot()
                if not root then return end
                local pos = root.Position
                local parts = getCoinParts()
                for n = 1, #parts do
                    local part = parts[n]
                    if part and part.Parent and (pos - part.Position).Magnitude <= auraRadius then
                        touch(root, part)
                    end
                end
            end
            local function hasTool(name)
                local char, bp = LocalPlayer.Character, LocalPlayer:FindFirstChild("Backpack")
                return (char and char:FindFirstChild(name)) or (bp and bp:FindFirstChild(name))
            end
            local function doKillAll()
                local char = LocalPlayer.Character
