                    Text = label, TextColor3 = C.text, TextSize = 15, Font = Enum.Font.Gotham, AutoButtonColor = false })
                corner(b, 12); stroke(b, C.border, .5)
                b.MouseButton1Click:Connect(fn)
                b.Activated:Connect(fn)
