                local left = math.ceil(roundTimerEndsAt - os.clock())
                if left > 0 then
                    thisGui.Text = formatRoundTime(left)
                else
                    resetRoundTimer()
                    thisGui.Text = "WAITING"
                end
            else
                thisGui.Text = "WAITING"
            end
            task.wait(.25)
        end
    end)
end

